sealed interface MTPhelp_AppUpdate : TlObject

class MTPDhelp_appUpdate(
    val is_can_not_skip: Boolean = false,
    val vid: Int,
    val vversion: String,
    val vtext: String,
    val ventities: List<MTPMessageEntity>,
    val vdocument: MTPDocument? = null,
    val vurl: String? = null,
    val vsticker: MTPDocument? = null,
) : MTPhelp_AppUpdate {
    override val constructorId: Int get() = CONSTRUCTOR
    override fun serializeBody(w: TlWriter) {
        w.int((if (is_can_not_skip) 1 else 0) or (if (vdocument != null) 2 else 0) or (if (vurl != null) 4 else 0) or (if (vsticker != null) 8 else 0))
        w.int(vid)
        w.string(vversion)
        w.string(vtext)
        w.vector(ventities) { it.serialize(w) }
        vdocument?.let { it.serialize(w) }
        vurl?.let { w.string(it) }
        vsticker?.let { it.serialize(w) }
    }
    companion object {
        const val CONSTRUCTOR: Int = 0xccbbce30.toInt()
        fun read(r: TlReader): MTPDhelp_appUpdate {
            val _flags = r.int()
            val is_can_not_skip = (_flags and 1) != 0
            val vid = r.int()
            val vversion = r.string()
            val vtext = r.string()
            val ventities = r.vector { r.obj() as MTPMessageEntity }
            val vdocument = if ((_flags and 2) != 0) r.obj() as MTPDocument else null
            val vurl = if ((_flags and 4) != 0) r.string() else null
            val vsticker = if ((_flags and 8) != 0) r.obj() as MTPDocument else null
            return MTPDhelp_appUpdate(is_can_not_skip, vid, vversion, vtext, ventities, vdocument, vurl, vsticker)
        }
    }
}

